package com.auth.websocket;

import java.security.MessageDigest;
import java.security.SecureRandom;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.Base64;
import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;

@ServerEndpoint("/ws/auth")
public class CrossServiceAuthEndpoint {

    private static final ConcurrentHashMap<String, SessionContext> activeSessions = new ConcurrentHashMap<>();
    private static final TokenGenerator tokenGenerator = new TokenGenerator();

    @OnOpen
    public void onOpen(Session session) {
        String challengeToken = tokenGenerator.generateChallenge();
        SessionContext ctx = new SessionContext(session, challengeToken);
        activeSessions.put(session.getId(), ctx);
        session.getAsyncRemote().sendText("{\"challenge\":\"" + challengeToken + "\"}");
    }

    @OnMessage
    public void onMessage(String message, Session session) throws Exception {
        SessionContext ctx = activeSessions.get(session.getId());
        if (ctx == null) {
            session.close(new CloseReason(CloseReason.CloseCodes.VIOLATED_POLICY, "No session"));
            return;
        }

        AuthRequest req = AuthRequest.parse(message);
        if (req == null) {
            session.getAsyncRemote().sendText("{\"error\":\"malformed request\"}");
            return;
        }

        if ("auth_response".equals(req.type)) {
            // Reject unknown/invalid service IDs and missing tokens before comparison.
            if (req.serviceId == null || req.responseToken == null
                    || !ServiceRegistry.isKnownService(req.serviceId)) {
                session.getAsyncRemote().sendText("{\"error\":\"auth failed\"}");
                return;
            }

            String expectedResponse = computeExpectedResponse(ctx.challengeToken, req.serviceId);
            byte[] expectedBytes = expectedResponse.getBytes(StandardCharsets.UTF_8);
            byte[] providedBytes = req.responseToken.getBytes(StandardCharsets.UTF_8);
            if (MessageDigest.isEqual(expectedBytes, providedBytes)) {
                String sessionToken = tokenGenerator.generateSessionToken(req.serviceId);
                ctx.authenticated = true;
                ctx.serviceId = req.serviceId;
                ctx.sessionToken = sessionToken;
                session.getAsyncRemote().sendText("{\"session_token\":\"" + sessionToken + "\"}");
            } else {
                session.getAsyncRemote().sendText("{\"error\":\"auth failed\"}");
            }
        } else if ("request".equals(req.type)) {
            if (!ctx.authenticated) {
                session.getAsyncRemote().sendText("{\"error\":\"not authenticated\"}");
                return;
            }
            handleServiceRequest(ctx, req, session);
        }
    }

    @OnClose
    public void onClose(Session session) {
        activeSessions.remove(session.getId());
    }

    private String computeExpectedResponse(String challenge, String serviceId) throws Exception {
        String sharedSecret = ServiceRegistry.getSharedSecret(serviceId);
        if (sharedSecret == null) {
            // Unknown service: no valid secret exists, so no valid response can be computed.
            throw new IllegalArgumentException("Unknown service");
        }
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(challenge.getBytes("UTF-8"));
        md.update(sharedSecret.getBytes("UTF-8"));
        return Base64.getEncoder().encodeToString(md.digest());
    }

    private void handleServiceRequest(SessionContext ctx, AuthRequest req, Session session) {
        session.getAsyncRemote().sendText("{\"status\":\"processed\",\"service\":\"" + ctx.serviceId + "\"}");
    }
}

class TokenGenerator {
    private final SecureRandom masterRandom;
    private final AtomicLong sequenceCounter;
    private volatile long lastReseedTime;
    private static final long RESEED_INTERVAL_MS = 300000; // 5 minutes

    TokenGenerator() {
        this.masterRandom = new SecureRandom();
        this.sequenceCounter = new AtomicLong(System.nanoTime());
        this.lastReseedTime = System.currentTimeMillis();
    }

    String generateChallenge() {
        byte[] challengeBytes = new byte[32];
        getSeededRandom().nextBytes(challengeBytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(challengeBytes);
    }

    String generateSessionToken(String serviceId) {
        long seq = sequenceCounter.incrementAndGet();
        byte[] tokenData = new byte[48];
        getSeededRandom().nextBytes(tokenData);
        ByteBuffer buf = ByteBuffer.wrap(tokenData);
        buf.putLong(40, seq);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(tokenData);
    }

    private SecureRandom getSeededRandom() {
        long now = System.currentTimeMillis();
        if (now - lastReseedTime > RESEED_INTERVAL_MS) {
            synchronized (this) {
                if (now - lastReseedTime > RESEED_INTERVAL_MS) {
                    masterRandom.setSeed(deriveReseedMaterial(now));
                    lastReseedTime = now;
                }
            }
        }
        return createDerivedRandom(now);
    }

    private byte[] deriveReseedMaterial(long timestamp) {
        byte[] material = new byte[32];
        masterRandom.nextBytes(material);
        ByteBuffer.wrap(material).putLong(0, timestamp);
        return material;
    }

    private SecureRandom createDerivedRandom(long timestamp) {
        byte[] seedBytes = new byte[32];
        masterRandom.nextBytes(seedBytes);
        SecureRandom derived = new SecureRandom(seedBytes);
        return derived;
    }
}

class SessionContext {
    final Session session;
    final String challengeToken;
    volatile boolean authenticated;
    volatile String serviceId;
    volatile String sessionToken;

    SessionContext(Session session, String challengeToken) {
        this.session = session;
        this.challengeToken = challengeToken;
    }
}

class AuthRequest {
    String type;
    String serviceId;
    String responseToken;
    String payload;

    static AuthRequest parse(String json) {
        try {
            AuthRequest req = new AuthRequest();
            // Simplified JSON parsing for demonstration
            if (json.contains("\"type\"")) {
                req.type = extractField(json, "type");
                req.serviceId = extractField(json, "service_id");
                req.responseToken = extractField(json, "response_token");
                req.payload = extractField(json, "payload");
                return req;
            }
            return null;
        } catch (Exception e) {
            return null;
        }
    }

    private static String extractField(String json, String field) {
        String key = "\"" + field + "\":\"";
        int start = json.indexOf(key);
        if (start == -1) return null;
        start += key.length();
        int end = json.indexOf("\"", start);
        if (end == -1) return null;
        return json.substring(start, end);
    }
}

class ServiceRegistry {
    private static final ConcurrentHashMap<String, String> secrets = new ConcurrentHashMap<>();
    static {
        // Load secrets from environment / secure configuration rather than hardcoding them.
        loadSecret("payment-service", "PAYMENT_SERVICE_SECRET");
        loadSecret("inventory-service", "INVENTORY_SERVICE_SECRET");
        loadSecret("notification-service", "NOTIFICATION_SERVICE_SECRET");
    }

    private static void loadSecret(String serviceId, String envVar) {
        String value = System.getenv(envVar);
        if (value != null && !value.isEmpty()) {
            secrets.put(serviceId, value);
        }
    }

    static boolean isKnownService(String serviceId) {
        return serviceId != null && secrets.containsKey(serviceId);
    }

    static String getSharedSecret(String serviceId) {
        // Return null for unknown services instead of a usable fallback secret,
        // so authentication cannot succeed against unregistered service IDs.
        return serviceId == null ? null : secrets.get(serviceId);
    }
}
